$root = (Get-Location).Path
$ov = Join-Path $root 'UXB_TYPED_TASK_ROUTINES_REAL_20260728\overlay'
Get-ChildItem $ov -Recurse -File | ForEach-Object {
  $rel = $_.FullName.Substring($ov.Length+1)
  $target = Join-Path $root $rel
  if (-not (Test-Path $target)) { [PSCustomObject]@{Durum='EKSIK'; Dosya=$rel} }
  else {
    $h1 = (Get-FileHash $_.FullName -Algorithm SHA256).Hash
    $h2 = (Get-FileHash $target -Algorithm SHA256).Hash
    if ($h1 -eq $h2) { [PSCustomObject]@{Durum='AYNI'; Dosya=$rel} } else { [PSCustomObject]@{Durum='FARKLI'; Dosya=$rel} }
  }
} | Sort-Object Durum, Dosya | Format-Table -AutoSize -Wrap

$root = (Get-Location).Path
$ov = Join-Path $root 'UXB_TYPED_TASK_ROUTINES_REAL_20260728\overlay'
Get-ChildItem $ov -Recurse -File | ForEach-Object {
  $rel = $_.FullName.Substring($ov.Length+1)
  $target = Join-Path $root $rel
  if (-not (Test-Path $target)) { [PSCustomObject]@{Durum='EKSIK'; Dosya=$rel}; return }
  $a = [IO.File]::ReadAllText($_.FullName) -replace "`r`n","`n"
  $b = [IO.File]::ReadAllText($target)     -replace "`r`n","`n"
  if ($a -eq $b) { [PSCustomObject]@{Durum='AYNI'; Dosya=$rel} } else { [PSCustomObject]@{Durum='FARKLI'; Dosya=$rel} }
} | Group-Object Durum | ForEach-Object { "$($_.Name): $($_.Count)" }
Write-Output "=== FARKLI OLANLAR ==="
Get-ChildItem $ov -Recurse -File | ForEach-Object {
  $rel = $_.FullName.Substring($ov.Length+1)
  $target = Join-Path $root $rel
  if (Test-Path $target) {
    $a = [IO.File]::ReadAllText($_.FullName) -replace "`r`n","`n"
    $b = [IO.File]::ReadAllText($target)     -replace "`r`n","`n"
    if ($a -ne $b) { "$rel  (overlay=$($a.Length) / src=$($b.Length))" }
  }
}

if (Test-Path .\bin\uxb.exe) { Get-Item .\bin\uxb.exe | Select-Object FullName, Length, LastWriteTime | Format-List } else { "bin\uxb.exe YOK" }
Write-Output "=== build ==="
Get-ChildItem .\build -File -ErrorAction SilentlyContinue | Sort-Object LastWriteTime -Descending | Select-Object -First 5 Name, LastWriteTime

