[CmdletBinding()]
param(
    [string]$Uxb = ".\bin\uxb.exe",
    [string]$TestRoot = ".\tests\typed_task_routines",
    [string]$ReportRoot = ".\reports\typed_task_routines",
    [switch]$SkipAst,
    [switch]$SkipMir,
    [switch]$EmitMirX64
)

$ErrorActionPreference = "Stop"

function Invoke-UxbChecked {
    param(
        [Parameter(Mandatory = $true)][string]$Label,
        [Parameter(Mandatory = $true)][string[]]$Arguments,
        [Parameter(Mandatory = $true)][bool]$ExpectSuccess
    )

    Write-Host "[$Label] $Uxb $($Arguments -join ' ')"
    & $Uxb @Arguments
    $code = $LASTEXITCODE
    if ($ExpectSuccess -and $code -ne 0) { throw "$Label failed with exit code $code" }
    if (-not $ExpectSuccess -and $code -eq 0) { throw "$Label unexpectedly succeeded" }
}

if (-not (Test-Path -LiteralPath $Uxb -PathType Leaf)) { throw "uXBasic compiler not found: $Uxb" }
if (-not (Test-Path -LiteralPath $TestRoot -PathType Container)) { throw "Test directory not found: $TestRoot" }
New-Item -ItemType Directory -Force -Path $ReportRoot | Out-Null

$positive = Get-ChildItem -LiteralPath $TestRoot -Filter "0*.uxb" | Sort-Object Name
$negative = Get-ChildItem -LiteralPath $TestRoot -Filter "negative_*.uxb" | Sort-Object Name

foreach ($test in $positive) {
    $base = $test.BaseName
    if (-not $SkipAst) {
        Invoke-UxbChecked -Label "AST/$($test.Name)" -ExpectSuccess $true -Arguments @(
            "int", $test.FullName, "--interpreter-backend", "AST",
            "--stdout-out", (Join-Path $ReportRoot "${base}_ast_stdout.txt")
        )
    }
    if (-not $SkipMir) {
        Invoke-UxbChecked -Label "MIR/$($test.Name)" -ExpectSuccess $true -Arguments @(
            "int", $test.FullName, "--interpreter-backend", "MIR",
            "--mir-program-output-out", (Join-Path $ReportRoot "${base}_mir_stdout.txt")
        )
    }
    if ($EmitMirX64) {
        Invoke-UxbChecked -Label "MIR-x64/$($test.Name)" -ExpectSuccess $true -Arguments @(
            "x64", $test.FullName, "--codegen-source", "MIR", "--x64-mode", "MIR",
            "--emit-x64-nasm-out", (Join-Path $ReportRoot "${base}_mir.asm")
        )
    }
}

foreach ($test in $negative) {
    Invoke-UxbChecked -Label "NEGATIVE/$($test.Name)" -ExpectSuccess $false -Arguments @(
        "sem", $test.FullName, "--stop-after", "sem"
    )
}

Write-Host "PASS: $($positive.Count) positive and $($negative.Count) negative tests completed."
exit 0

