param(
    [string]$Uxb = ".\bin\uxb.exe",
    [string[]]$Dirs = @(
        ".\tests\adim36_full_surface\positive",
        ".\tests\adim30_10step\positive",
        ".\tests\adim04\positive",
        ".\tests\adim10\positive"
    ),
    [string]$WorkDir = "$env:TEMP\uxb_parity"
)

$ErrorActionPreference = "Continue"
New-Item -ItemType Directory -Force -Path $WorkDir | Out-Null

function Norm([string]$p) {
    if (-not (Test-Path -LiteralPath $p)) { return $null }
    $t = [IO.File]::ReadAllText($p) -replace "`r`n", "`n"
    return $t.TrimEnd("`n", " ", "`t")
}

$rows = @()
foreach ($d in $Dirs) {
    if (-not (Test-Path $d)) { continue }
    foreach ($f in (Get-ChildItem -LiteralPath $d -Filter *.bas | Sort-Object Name)) {
        $astOut = Join-Path $WorkDir "$($f.BaseName)_ast.txt"
        $mirOut = Join-Path $WorkDir "$($f.BaseName)_mir.txt"
        Remove-Item -LiteralPath $astOut, $mirOut -Force -ErrorAction SilentlyContinue

        & $Uxb int $f.FullName --interpreter-backend AST --stdout-out $astOut *> $null
        $astCode = $LASTEXITCODE
        & $Uxb int $f.FullName --interpreter-backend MIR --mir-program-output-out $mirOut *> $null
        $mirCode = $LASTEXITCODE

        $a = Norm $astOut
        $m = Norm $mirOut

        $status = ""
        if ($astCode -ne 0 -and $mirCode -ne 0) { $status = "BOTH_FAIL" }
        elseif ($astCode -ne 0) { $status = "AST_ONLY_FAIL" }
        elseif ($mirCode -ne 0) { $status = "MIR_ONLY_FAIL" }
        elseif ($null -eq $a -and $null -eq $m) { $status = "NO_OUTPUT" }
        elseif ($a -eq $m) { $status = "MATCH" }
        else { $status = "MISMATCH" }

        $rows += [PSCustomObject]@{
            Test = $f.Name; Status = $status; AstExit = $astCode; MirExit = $mirCode; Ast = $a; Mir = $m
        }
    }
}

$rows | Group-Object Status | Sort-Object Name | ForEach-Object { "{0,-16} {1}" -f $_.Name, $_.Count }
Write-Output ""
Write-Output "=== MISMATCH detaylari ==="
